  /**
   * Merges the NodeToLabelsInfo of every SubCluster into a single one.
   *
   * Each SubCluster returns the node-to-labels mapping of the nodes it
   * manages. Nodes are unique per SubCluster, but in case the same node is
   * reported by more than one SubCluster we merge the labels avoiding
   * duplicates.
   *
   * @param nodeToLabelsInfoMap the NodeToLabelsInfo of each SubCluster
   * @return a NodeToLabelsInfo containing the merged node-to-labels mapping
   */
  public static NodeToLabelsInfo mergeNodeToLabels(
      Map<SubClusterInfo, NodeToLabelsInfo> nodeToLabelsInfoMap) {

    Map<String, Set<NodeLabel>> nodeLabelsMap = new LinkedHashMap<>();

    for (NodeToLabelsInfo nodeToLabelsInfo : nodeToLabelsInfoMap.values()) {
      if (nodeToLabelsInfo == null) {
        continue;
      }
      for (Entry<String, NodeLabelsInfo> entry : nodeToLabelsInfo
          .getNodeToLabels().entrySet()) {
        Set<NodeLabel> nodeLabels = nodeLabelsMap.get(entry.getKey());
        if (nodeLabels == null) {
          nodeLabels = new LinkedHashSet<>();
          nodeLabelsMap.put(entry.getKey(), nodeLabels);
        }
        NodeLabelsInfo nodeLabelsInfo = entry.getValue();
        if (nodeLabelsInfo != null) {
          nodeLabels.addAll(nodeLabelsInfo.getNodeLabels());
        }
      }
    }

    NodeToLabelsInfo nodeToLabelsInfo = new NodeToLabelsInfo();
    for (Entry<String, Set<NodeLabel>> entry : nodeLabelsMap.entrySet()) {
      List<NodeLabel> nodeLabels = new ArrayList<>(entry.getValue());
      nodeToLabelsInfo.getNodeToLabels().put(entry.getKey(),
          new NodeLabelsInfo(nodeLabels));
    }
    return nodeToLabelsInfo;
  }

