/**
 * The YARN Router will forward the request to all the YARN RMs in parallel,
 * after that it will merge the node-to-labels mapping of every SubCluster.
 * <p>
 * Possible failure:
 * <p>
 * Client: identical behavior as {@code RMWebServices}.
 * <p>
 * Router: the Client will timeout and resubmit the request.
 * <p>
 * ResourceManager: the Router calls each YARN RM in parallel by using one
 * thread for each YARN RM. In case a YARN RM fails, a single call will
 * timeout. However the Router will merge the NodeToLabelsInfo it got, and
 * provides a partial mapping to the client.
 * <p>
 * State Store: the Router will timeout and it will retry depending on the
 * FederationFacade settings - if the failure happened before the select
 * operation.
 */
@Override
public NodeToLabelsInfo getNodeToLabels(HttpServletRequest hsr)
    throws IOException {
  try {
    long startTime = clock.getTime();
    Map<SubClusterId, SubClusterInfo> subClustersActive =
        getActiveSubclusters();
    final HttpServletRequest hsrCopy = clone(hsr);
    Class<?>[] argsClasses = new Class[]{HttpServletRequest.class};
    Object[] args = new Object[]{hsrCopy};
    ClientMethod remoteMethod =
        new ClientMethod("getNodeToLabels", argsClasses, args);
    Map<SubClusterInfo, NodeToLabelsInfo> nodeToLabelsInfoMap =
        invokeConcurrent(subClustersActive.values(), remoteMethod,
            NodeToLabelsInfo.class);
    NodeToLabelsInfo nodeToLabelsInfo =
        RouterWebServiceUtil.mergeNodeToLabels(nodeToLabelsInfoMap);
    if (nodeToLabelsInfo != null) {
      long stopTime = clock.getTime();
      routerMetrics.succeededGetNodeToLabelsRetrieved(stopTime - startTime);
      return nodeToLabelsInfo;
    }
  } catch (NotFoundException e) {
    routerMetrics.incrNodeToLabelsFailedRetrieved();
    RouterServerUtil.logAndThrowIOException(
        "Get all active sub cluster(s) error.", e);
  } catch (YarnException e) {
    routerMetrics.incrNodeToLabelsFailedRetrieved();
    RouterServerUtil.logAndThrowIOException("getNodeToLabels error.", e);
  }

  routerMetrics.incrNodeToLabelsFailedRetrieved();
  throw new RuntimeException("getNodeToLabels error.");
}

/**
 * Invokes the same method on all the given SubClusters in parallel.
 *
 * @param clusterIds the SubClusters we want to contact
 * @param request the method we want to invoke with its parameters
 * @param clazz the class of the expected response
 * @param <R> the type of the expected response
 * @return the responses of the SubClusters that replied correctly
 * @throws YarnException if none of the SubClusters replied correctly
 */
<R> Map<SubClusterInfo, R> invokeConcurrent(
    Collection<SubClusterInfo> clusterIds, ClientMethod request,
    Class<R> clazz) throws YarnException {

  // Send the requests in parallel
  Map<SubClusterInfo, Future<Object>> futures = new HashMap<>();
  for (final SubClusterInfo info : clusterIds) {
    Future<Object> future = this.threadpool.submit(() -> {
      DefaultRequestInterceptorREST interceptor =
          getOrCreateInterceptorForSubCluster(info.getSubClusterId(),
              info.getRMWebServiceAddress());
      Method method = DefaultRequestInterceptorREST.class
          .getMethod(request.getMethodName(), request.getTypes());
      return method.invoke(interceptor, request.getParams());
    });
    futures.put(info, future);
  }

  // Collect the responses
  Map<SubClusterInfo, R> results = new HashMap<>();
  Map<SubClusterInfo, Exception> exceptions = new HashMap<>();
  for (Entry<SubClusterInfo, Future<Object>> entry : futures.entrySet()) {
    SubClusterInfo subClusterInfo = entry.getKey();
    try {
      Object result = entry.getValue().get();
      results.put(subClusterInfo, clazz.cast(result));
    } catch (InterruptedException | ExecutionException e) {
      LOG.error("SubCluster {} failed to call {} method.",
          subClusterInfo.getSubClusterId(), request.getMethodName(), e);
      exceptions.put(subClusterInfo, e);
    }
  }

  if (results.isEmpty() && !exceptions.isEmpty()) {
    throw new YarnException("Unable to call " + request.getMethodName()
        + " on any sub cluster.",
        exceptions.values().iterator().next());
  }

  return results;
}

